package in.anumati.platform.grievance; import java.time.*; import java.util.*; public record GrievanceResponse(UUID id,UUID businessProfileId,UUID applicationId,String subject,String description,String department,GrievancePriority priority,GrievanceStatus status,String assignedTo,String resolution,Instant createdAt,Instant updatedAt,Instant closedAt){static GrievanceResponse from(Grievance g){return new GrievanceResponse(g.getId(),g.getBusinessProfile().getId(),g.getApplication()==null?null:g.getApplication().getId(),g.getSubject(),g.getDescription(),g.getDepartment(),g.getPriority(),g.getStatus(),g.getAssignedTo(),g.getResolution(),g.getCreatedAt(),g.getUpdatedAt(),g.getClosedAt());}}
